INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `allowOneResponsePerMember`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('04fbaa89-ff26-469a-96f9-7fb4a5796c54','የአባልነት እድሳት ቅጽ (ዓመታዊ)','በአዕማደ ሰላም ሰንበት ትምህርት ቤት የአገልግሎት አባላት ዓመታዊ ምዝገባ ማደሻና ቃል ኪዳን ማረጋገጫ ቅጽ','{\"titleAm\":\"የአባልነት እድሳት ቅጽ (ዓመታዊ)\",\"titleEn\":\"የአባልነት እድሳት ቅጽ (ዓመታዊ)\",\"descriptionAm\":\"በአዕማደ ሰላም ሰንበት ትምህርት ቤት የአገልግሎት አባላት ዓመታዊ ምዝገባ ማደሻና ቃል ኪዳን ማረጋገጫ ቅጽ\",\"descriptionEn\":\"በአዕማደ ሰላም ሰንበት ትምህርት ቤት የአገልግሎት አባላት ዓመታዊ ምዝገባ ማደሻና ቃል ኪዳን ማረጋገጫ ቅጽ\",\"fields\":[{\"name\":\"fullName\",\"type\":\"text\",\"labelAm\":\"ሙሉ ስም (ከነ አያት)\",\"labelEn\":\"Full Name\",\"required\":true,\"validation\":{\"minLength\":3,\"maxLength\":100}},{\"name\":\"baptismalName\",\"type\":\"text\",\"labelAm\":\"የክርስትና ስም\",\"labelEn\":\"Baptismal Name\",\"required\":true,\"validation\":{\"minLength\":2}},{\"name\":\"memberNo\",\"type\":\"text\",\"labelAm\":\"የአባልነት መለያ ቁጥር\",\"labelEn\":\"Member ID Number\",\"required\":true,\"validation\":{\"pattern\":\"^AS-\\\\d{4}-\\\\d{4}$\"},\"placeholderAm\":\"ምሳሌ፦ AS-2026-0001\"},{\"name\":\"phone\",\"type\":\"text\",\"labelAm\":\"ስልክ ቁጥር\",\"labelEn\":\"Phone Number\",\"required\":true,\"validation\":{\"minLength\":9,\"maxLength\":20}},{\"name\":\"email\",\"type\":\"text\",\"labelAm\":\"ኢሜይል አድራሻ\",\"labelEn\":\"Email Address\",\"required\":false,\"validation\":{\"pattern\":\"^[\\\\w-\\\\.]+@([\\\\w-]+\\\\.)+[\\\\w-]{2,4}$\"}},{\"name\":\"currentDepartment\",\"type\":\"dropdown\",\"labelAm\":\"ያሉበት የአገልግሎት ክፍል\",\"labelEn\":\"Current Service Department\",\"required\":true,\"options\":[{\"value\":\"ትምህርት\",\"labelAm\":\"የትምህርት ክፍል\",\"labelEn\":\"Education Department\"},{\"value\":\"መዝሙር\",\"labelAm\":\"የመዝሙር ክፍል\",\"labelEn\":\"Choir & Hymn Department\"},{\"value\":\"ልማት\",\"labelAm\":\"የልማትና ገቢ ማሰባሰቢያ ክፍል\",\"labelEn\":\"Development & Finance\"},{\"value\":\"ኪነጥበብ\",\"labelAm\":\"የኪነ ጥበብና ድራማ ክፍል\",\"labelEn\":\"Arts & Media\"},{\"value\":\"ሕፃናት\",\"labelAm\":\"የሕፃናትና ታዳጊዎች ክፍል\",\"labelEn\":\"Children & Youth\"}]},{\"name\":\"confessionFather\",\"type\":\"text\",\"labelAm\":\"የንስሐ አባት ስምና ቤተክርስቲያን\",\"labelEn\":\"Confession Father & Parish\",\"required\":true,\"validation\":{\"minLength\":3}},{\"name\":\"renewalYear\",\"type\":\"number\",\"labelAm\":\"የእድሳት ዓመተ ምሕረት (ዓ.ም)\",\"labelEn\":\"Renewal Year (E.C)\",\"required\":true,\"validation\":{\"min\":2015,\"max\":2030}},{\"name\":\"renewDate\",\"type\":\"date\",\"labelAm\":\"የማደሻ ቀን\",\"labelEn\":\"Renewal Date\",\"required\":true},{\"name\":\"serviceCommitment\",\"type\":\"radio\",\"labelAm\":\"የአገልግሎት ቁርጠኝነት ደረጃ\",\"labelEn\":\"Service Commitment Level\",\"required\":true,\"options\":[{\"value\":\"ሙሉ ጊዜ\",\"labelAm\":\"ሙሉ ጊዜ (በየሳምንቱ ቅዳሜና እሑድ)\",\"labelEn\":\"Full Time\"},{\"value\":\"በከፊል\",\"labelAm\":\"በከፊል (በተመረጡ ቀናት)\",\"labelEn\":\"Part Time\"},{\"value\":\"ልዩ ዝግጅት\",\"labelAm\":\"በልዩ በዓላትና ዝግጅቶች ብቻ\",\"labelEn\":\"Special Events Only\"}]},{\"name\":\"receiptFile\",\"type\":\"file\",\"labelAm\":\"የዓመታዊ መዋጮ ደረሰኝ ወይም ማረጋገጫ (ካለ)\",\"labelEn\":\"Payment / Contribution Receipt (Optional)\",\"required\":false,\"validation\":{\"allowedMimeTypes\":[\"image/jpeg\",\"image/png\",\"image/webp\",\"application/pdf\"],\"maxSizeBytes\":5242880}},{\"name\":\"agreement\",\"type\":\"checkbox\",\"labelAm\":\"የሰንበት ትምህርት ቤቱን መተዳደሪያ ደንብና መንፈሳዊ ሥነ-ምግባር አከብራለሁ\",\"labelEn\":\"I commit to following the Sunday School constitution and ethics\",\"required\":true}],\"settings\":{\"allowOneResponsePerMember\":true}}','open',NULL,1,'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1','2026-10-26 16:29:01.841','2026-10-26 16:29:02.679'),('0814e911-cbd3-4fb1-967a-3c4e13fb4636','የበጎ ፈቃድ አገልግሎት ምዝገባ ቅጽ','በሰንበት ትምህርት ቤቱ በተለያዩ የበጎ አድራጎት፣ የልማትና የማኅበራዊ አገልግሎት ዘርፎች ለመሳተፍ የተዘጋጀ ቅጽ','{\"titleAm\":\"የበጎ ፈቃድ አገልግሎት ምዝገባ ቅጽ\",\"titleEn\":\"Volunteer Ministry Sign-Up Form\",\"fields\":[{\"name\":\"volunteerName\",\"type\":\"text\",\"labelAm\":\"የበጎ ፈቃደኛው ስም\",\"labelEn\":\"Name\",\"required\":true},{\"name\":\"phone\",\"type\":\"text\",\"labelAm\":\"ስልክ ቁጥር\",\"labelEn\":\"Phone\",\"required\":true},{\"name\":\"profession\",\"type\":\"text\",\"labelAm\":\"የትምህርት ደረጃ ወይም ሙያ\",\"labelEn\":\"Profession\",\"required\":true},{\"name\":\"interestedMinistries\",\"type\":\"checkbox\",\"labelAm\":\"ለማገልገል የሚፈልጓቸው ዘርፎች\",\"labelEn\":\"Ministries\",\"required\":true,\"options\":[{\"value\":\"media\",\"labelAm\":\"ሚዲያና ቴክኖሎጂ\"},{\"value\":\"charity\",\"labelAm\":\"መርጃ ማዕድ\"}]},{\"name\":\"experienceSummary\",\"type\":\"textarea\",\"labelAm\":\"ቀደም ሲል የነበሩዎት ልምዶች\",\"labelEn\":\"Experience\",\"required\":true,\"validation\":{\"minLength\":10}},{\"name\":\"hasConfessionFather\",\"type\":\"radio\",\"labelAm\":\"የንስሐ አባት አሎት?\",\"labelEn\":\"Confession Father\",\"required\":true,\"options\":[{\"value\":\"yes\",\"labelAm\":\"አዎ አለኝ\"},{\"value\":\"no\",\"labelAm\":\"የለኝም\"}]}]}','open','2026-12-31 23:59:59.000',0,'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4','2026-10-17 17:56:57.185','2026-10-17 17:56:57.185'),('2d9586e8-8061-4ace-b669-3f6a971e1c6f','የ2019 ልዩ መንፈሳዊ ጉባኤና የአባላት ዳሰሳ ቅጽ','የአባላት የተሳትፎና የአገልግሎት ዝግጁነት መመዝገቢያ ቅጽ','{\"titleAm\":\"የ2019 ልዩ መንፈሳዊ ጉባኤና የአባላት ዳሰሳ ቅጽ\",\"titleEn\":\"Annual Spiritual Conference & Member Survey\",\"fields\":[{\"name\":\"spiritualName\",\"type\":\"text\",\"labelAm\":\"የክርስትና ስም\",\"labelEn\":\"Baptismal Name\",\"required\":true,\"validation\":{\"minLength\":3,\"maxLength\":50}},{\"name\":\"reflection\",\"type\":\"textarea\",\"labelAm\":\"የመንፈሳዊ ሕይወት አስተያየት\",\"labelEn\":\"Spiritual Life Reflection\",\"required\":true,\"validation\":{\"minLength\":10}},{\"name\":\"serviceYears\",\"type\":\"number\",\"labelAm\":\"በሰንበት ት/ቤት ያገለገሉበት ዓመታት\",\"labelEn\":\"Years in Ministry\",\"required\":true,\"validation\":{\"min\":1,\"max\":40}},{\"name\":\"registrationDate\",\"type\":\"date\",\"labelAm\":\"የምዝገባ ቀን\",\"labelEn\":\"Registration Date\",\"required\":true,\"validation\":{\"minDate\":\"2026-01-01\"}},{\"name\":\"departmentChoice\",\"type\":\"dropdown\",\"labelAm\":\"የተመረ