INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('016f2716-5f88-4de4-b0e1-e6e5967f7f20','saint_of_day','የዕለቱ ቅዱስ፡ አባ ጳውሊ ታላቁ ገዳማዊ','የገዳማዊ ሕይወት ቀዳሚ የሆኑት አባ ጳውሊ በበረሃ የኖሩበት ገድልና ድንቅ መንፈሳዊ ተጋድሎ።',NULL,0,'2026-10-17 17:56:56.859',NULL,'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4','2026-10-17 17:56:56.859','2026-10-17 17:56:56.859'),('3ea6a392-36e5-4719-b98a-6b28a93ba8e4','teaching','ስለ አሥራትና በኩራት ትምህርት','«በቤቴ ውስጥ መብል እንዲሆን አሥራቱን ሁሉ ወደ ጎተራ አግቡ» - ሚልክያስ ፫:፲። የክርስትና የልግስና መርሆዎች።',NULL,0,'2026-10-17 17:56:56.892',NULL,'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4','2026-10-17 17:56:56.892','2026-10-17 17:56:56.892'),('6807c844-591a-47ae-b722-72ad17a89976','sinksar','የዕለቱ ስንክሳር ጥቅምት ፯ - 8490','<p>ይህ የዕለቱ ስንክሳር ንባብና የቅዱሳን አበው ገድል ነው።</p>',NULL,1,'2026-10-17 18:09:00.000',NULL,'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1','2026-10-17 18:09:49.057','2026-10-17 18:09:49.057'),('fe551855-4ec4-4569-bd32-9744e4dfb366','sinksar','የጥቅምት ወር የበዓላት ማውጫ','በዚህ ወር የሚከበሩ ዓበይትና ንዑሳን የቅዱሳን በዓላት ዝርዝርና መርሐ ግብራቸው።',NULL,0,'2026-10-17 17:56:56.898',NULL,'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4','2026-10-17 17:56:56.898','2026-10-17 17:56:56.898'),('fe6a11c0-fd9e-4247-a702-d0316ebc7724','news','የአዲስ ተማሪዎች ምዝገባ ተጀመረ','ለ2019 ዓ.ም የትምህርት ዘመን ከደረጃ ፩ እስከ ፬ የአዲስ ተማሪዎች ምዝገባ በይፋ ተከፍቷል።',NULL,0,'2026-10-17 17:56:56.886',NULL,'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4','2026-10-17 17:56:56.886','2026-10-17 17:56:56.886');
